import bounds from '../assets/enemies/bounds-v1.json' with {type:'json'};
import {ENEMIES} from './enemy-roster.mjs';
const intro={M01:'近身双钳与尾刺，留意蓄力后的突袭。',M02:'前足连刺，持续追击靠近的旅者。',M03:'在空中追击，收翼后俯冲撕咬。',M04:'举起重锤后猛砸，收招时有反击机会。',M05:'移动灵活，双镰接连切入近身。',M06:'盾击后接短剑刺，适合拉开距离。',M07:'保持距离口喷毒液，毒池会持续伤害。',M08:'抛射毒囊，在落点留下危险区域。',M09:'从远处投射暗羽，利用平台避开弹道。',M10:'钩斧近战与锁链远投交替施压。'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function enemyPortraitStyle(id){const m=bounds.units[id],f=m.frames[6],r=f.rect,b=f.bbox,animal=ENEMIES[id].form==='wolf',side=Math.min(r[2],Math.max(b[3]*(animal?.68:.57),b[2]*(animal?.66:.56))),cx=r[0]+b[0]+b[2]*(animal?.79:.55),cy=r[1]+b[1]+b[3]*(animal?.4:.24),x=Math.max(r[0],Math.min(r[0]+r[2]-side,cx-side/2)),y=Math.max(r[1],Math.min(r[1]+r[3]-side,cy-side/2));return `background-image:url('assets/enemies/${m.file}');background-size:${m.size[0]/side*100}% ${m.size[1]/side*100}%;background-position:${x/(m.size[0]-side)*100}% ${y/(m.size[1]-side)*100}%`;}
export function renderEncounterCards(stage){const card=(id,boss=false)=>{const d=ENEMIES[id],copy=d.boss?(d.passiveText||d.trait):intro[id];return `<button class="encounter-card has-tip ${boss?'encounter-boss':''}" data-tip="${escape(d.name+'：'+copy)}" aria-label="${escape(d.name)}，查看简介"><i class="enemy-portrait" style="${enemyPortraitStyle(id)}"></i><strong>${d.name}</strong></button>`;};return `<section class="encounter-boss-group"><small>守关首领</small>${card(stage.boss,true)}</section><section class="encounter-minions"><small>本关妖兽</small><div>${card(stage.melee)}${card(stage.ranged)}</div></section>`;}
